  "sql": "WITH _base_2 AS (\n  SELECT\n    orders.customer AS \"orders.customer\",\n    SUM(orders.subtotal) / 100.0 AS \"orders.spend\",\n    CAST(MIN(orders.ordered_at) AS TIMESTAMP) AS \"orders.first_at\"\n  FROM orders AS orders\n  GROUP BY\n    orders.customer\n), _cm_orders__store_id_first AS (\n  SELECT\n    _val_0 AS \"orders.customer\",\n    MAX(CASE WHEN _ranked_rn = 1 THEN _val_1 END) AS \"orders.first_store\"\n  FROM (\n    SELECT\n      orders.customer AS _val_0,\n      orders.store_id AS _val_1,\n      ROW_NUMBER() OVER (PARTITION BY orders.customer ORDER BY orders.ordered_at) AS _ranked_rn\n    FROM orders AS orders\n  ) AS _ranked_src\n  GROUP BY\n    _val_0\n), __slayer_stage_cust AS (\n  SELECT\n    _stage_inner.\"orders.customer\" AS \"customer\",\n    _stage_inner.\"orders.first_store\" AS \"first_store\",\n    _stage_inner.\"orders.spend\" AS \"spend\",\n    _stage_inner.\"orders.first_at\" AS \"first_at\"\n  FROM (\n    SELECT\n      _base_2.\"orders.customer\",\n      _cm_orders__store_id_first.\"orders.first_store\",\n      _base_2.\"orders.spend\",\n      _base_2.\"orders.first_at\"\n    FROM _base_2\n    LEFT JOIN _cm_orders__store_id_first\n      ON _base_2.\"orders.customer\" IS NOT DISTINCT FROM _cm_orders__store_id_first.\"orders.customer\"\n  ) AS _stage_inner\n)\nSELECT\n  cust.first_store AS \"cust.first_store\",\n  COUNT(*) AS \"cust.n\",\n  CAST(AVG(cust.spend) AS DOUBLE) AS \"cust.avg_spend\"\nFROM __slayer_stage_cust AS cust\nGROUP BY\n  cust.first_store\nORDER BY\n  \"cust.first_store\" ASC\nLIMIT 101"
}

